"""Completion API, source-flow and lifetime lessons from pinned Linux v6.12."""
ROWS = [
('Completion 구조·완료 토큰과 swait 대기열', 'include/linux/completion.h', 'completion',
 'completion은 unsigned int done과 swait_queue_head wait를 가집니다. done은 단순 task 수가 아니라 소비 가능한 완료 표시의 수를 표현하며 UINT_MAX는 영구 완료의 특수 상태입니다. head의 raw 잠금이 done 갱신과 대기열 연결을 보호합니다. 완료를 기다리는 동기화 지점이지 mutex 소유권을 전달하는 객체는 아닙니다. 먼저 complete를 호출해도 표시가 남으므로 나중 waiter가 소비할 수 있습니다.',
 '작업 결과가 준비된 사건을 표현하는 이름으로 객체를 만드세요. 초기화, 대기와 완료 통지를 나누고 결과 데이터의 수명도 보장합니다. 잠금 소유권이나 현재 waiter 수를 done 값으로 추론하지 않습니다.',
 [('done 값은 무엇을 표현하나요?', '소비 가능한 완료 표시와 영구 완료 sentinel입니다.', '항상 잠든 task의 정확한 수입니다.', 'complete는 표시를 증가시키고 waiter는 소비합니다. 연결된 task 수와 done 값은 별도로 관리됩니다.'),
  ('waiter보다 complete가 먼저 호출되면 표시가 사라지나요?', '아닙니다. 나중 waiter가 소비할 수 있습니다.', '맞습니다. 당시 task가 없으면 무조건 잃습니다.', 'done은 대기열 항목 유무와 독립적으로 증가합니다. 이 저장된 사건 표시가 단순 깨움 호출과 다른 점입니다.')]),
('Completion 초기화·init과 reinit의 차이', 'include/linux/completion.h', 'init_completion',
 'init_completion은 done을 0으로 만들고 swait head도 초기화합니다. reinit_completion은 done만 0으로 바꾸며 대기열을 초기화하지 않습니다. 사용 중인 객체에 init을 다시 호출하면 대기열 연결을 잃을 수 있습니다. reinit도 경쟁 중인 대기나 완료 통지를 자동으로 안전하게 만드는 함수는 아니며 다음 사건 주기와 이전 사용자의 종료를 외부 규약으로 구분해야 합니다.',
 '최초 초기화는 사용 전에 수행하세요. 재사용할 때는 이전 waiter와 완료 통지가 더 이상 객체를 사용하지 않는지 확인한 뒤 reinit합니다. 초기화 함수를 단순 오류 복구나 경쟁 취소 함수로 사용하지 마세요.',
 [('reinit_completion이 swait head도 새로 초기화하나요?', '아닙니다. done만 0으로 만듭니다.', '맞습니다. 모든 리스트를 비웁니다.', '두 inline 함수의 본문을 비교하세요. reinit은 대기열 링크를 유지하지만 동시 사용의 안전 조건을 없애지는 않습니다.'),
  ('사용 중인 객체에 init_completion을 다시 호출해도 등록이 보존되나요?', '아닙니다. head 재초기화로 연결을 잃을 수 있습니다.', '맞습니다. 기존 task를 자동으로 옮깁니다.', '공식 문서는 재초기화된 빈 대기열에서 task가 사라질 위험을 설명합니다. 처음 초기화와 사건 주기 재설정은 구별하세요.')]),
('Completion 스택 선언·lockdep와 객체 수명', 'include/linux/completion.h', 'DECLARE_COMPLETION_ONSTACK',
 '정적 DECLARE_COMPLETION은 done 0과 빈 swait head를 구성합니다. 스택 객체에는 ONSTACK 선언을 사용하여 제한된 수명을 명시하고 CONFIG_LOCKDEP일 때 실행 중 초기화를 수행합니다. MAP 변형과 init_completion_map도 헤더의 초기화 연결을 따릅니다. timeout이나 signal로 waiter가 먼저 돌아와도 다른 worker가 나중에 complete를 호출할 수 있으므로 스택 함수의 반환이 객체 사용 종료와 같은 것은 아닙니다.',
 '비동기 worker가 객체를 참조하는 동안 스택이 사라지지 않도록 종료·취소·참조 수명 규약을 설계하세요. 필요하면 더 오래 살아 있는 객체 안에 completion을 둡니다. ONSTACK 이름이 자동 수명 연장을 제공하지는 않습니다.',
 [('ONSTACK 선언이 worker 종료까지 스택 메모리를 자동으로 유지하나요?', '아닙니다. 호출자가 사용 종료를 보장해야 합니다.', '맞습니다. timeout 뒤에도 영구히 보관됩니다.', '매크로는 초기화와 lockdep 문맥을 준비합니다. 비동기 사용자 수명이나 함수 반환 시점은 별도 프로토콜의 책임입니다.'),
  ('timeout으로 대기가 끝나면 다른 complete 호출도 자동 취소되나요?', '아닙니다. 관련 비동기 활동을 따로 정리해야 합니다.', '맞습니다. waiter 반환이 worker를 삭제합니다.', '공식 문서는 조기 반환 뒤에도 complete나 reinit이 객체를 사용할 수 있다고 강조합니다. 대기 종료와 작업 취소는 다른 동작입니다.')]),
('Completion complete·포화 증가와 한 항목 깨움', 'kernel/sched/completion.c', 'complete_with_flags',
 'complete_with_flags는 IRQ 상태를 저장하고 raw head 잠금을 잡습니다. done이 UINT_MAX가 아니면 하나 증가시키고 swake_up_locked로 첫 항목을 처리한 뒤 이전 IRQ 상태를 복구합니다. 최대값에서는 증가를 생략하므로 unsigned wrap으로 0이 되지 않습니다. 기다리는 task가 없어도 done 증가가 남습니다. 잠금 아래의 표시 갱신과 task 깨움은 서로 연결되지만 작업의 후속 결과 소비까지 실행하는 것은 아닙니다.',
 '작업 결과를 준비한 뒤 completion을 통지하는 프로토콜로 사용하세요. complete가 반환했다고 waiter의 후속 작업이 끝났다고 판단하지 않습니다. 여러 complete 호출의 표시와 여러 wait 호출의 소비를 대응시켜 봅니다.',
 [('done이 UINT_MAX일 때 complete는 0으로 wrap하나요?', '아닙니다. 증가를 생략합니다.', '맞습니다. unsigned이므로 항상 wrap합니다.', '조건문은 sentinel에서 증가를 막습니다. 숫자 자료형의 일반 연산 성질과 실제 분기 동작을 구별하세요.'),
  ('대기열이 비어 있어도 done이 증가하나요?', '그렇습니다. 최대값이 아니면 증가합니다.', '아닙니다. 반드시 waiter가 있어야 증가합니다.', 'done 증가와 swake 호출은 항목 존재 검사보다 상위에 있습니다. 먼저 발생한 완료 표시를 나중에 소비할 수 있습니다.')]),
('Completion current CPU·깨움 플래그 전달', 'kernel/sched/completion.c', 'complete_on_current_cpu',
 '일반 complete는 complete_with_flags에 0을 전달하고 current CPU 변형은 WF_CURRENT_CPU를 전달합니다. done 증가와 head 잠금 규칙은 동일합니다. 플래그는 swait의 try_to_wake_up으로 이어지며 실제 CPU 선택은 scheduler가 처리합니다. 이 함수에서 결과 데이터를 다른 CPU로 복사하거나 모든 waiter를 처리하는 것은 아닙니다.',
 '일반 통지와 current CPU 힌트의 차이를 따라가세요. 플래그 전달을 task 작업 완료 보장으로 해석하지 않습니다. 실제 배치 효과를 알아보려면 scheduler의 해당 플래그 처리와 호출 문맥을 함께 봅니다.',
 [('current CPU 변형이 전달하는 플래그는 무엇인가요?', 'WF_CURRENT_CPU입니다.', '항상 WQ_FLAG_EXCLUSIVE입니다.', 'complete_on_current_cpu의 인자와 swake_up_locked로 이어지는 전달을 확인하세요. 등록 플래그와 scheduler 깨움 플래그는 다릅니다.'),
  ('current CPU 변형이 complete_all과 같은 전체 깨움인가요?', '아닙니다. 공통 single 통지 경로입니다.', '맞습니다. CPU의 모든 task를 깨웁니다.', '이 wrapper는 complete_with_flags를 사용합니다. sentinel 설정과 전체 리스트 처리는 complete_all의 별도 동작입니다.')]),
('Completion complete_all·현재와 미래 waiter의 영구 완료', 'kernel/sched/completion.c', 'complete_all',
 'complete_all은 raw 잠금 아래 done을 UINT_MAX로 설정하고 completion 전용 swake_up_all_locked로 현재 항목을 모두 처리합니다. 이후 waiter도 sentinel을 소비하지 않으므로 reinit 전까지 계속 통과할 수 있습니다. 함수는 RT 관련 문맥 검사를 먼저 수행합니다. 따라서 일반 swait의 IRQ 활성 all 함수와 같은 구현이 아니며 반복마다 잠금을 푸는 규칙도 적용되지 않습니다.',
 '한 사건에 여러 현재·미래 사용자가 통과해야 할 때 계약을 확인합니다. 다음 사건을 위해 재사용하려면 모든 이전 사용자가 끝났음을 보장한 뒤 reinit하세요. RT의 threaded 문맥 요구와 호출자 수명 규약도 확인합니다.',
 [('complete_all 뒤의 waiter가 UINT_MAX를 하나 줄이나요?', '아닙니다. sentinel은 소비하지 않습니다.', '맞습니다. 모든 wait가 최대값을 줄입니다.', '공통 소비 분기는 done != UINT_MAX일 때만 감소합니다. 그래서 현재뿐 아니라 나중 waiter도 통과할 수 있습니다.'),
  ('complete_all은 일반 swake_up_all을 그대로 호출하나요?', '아닙니다. all_locked를 사용합니다.', '맞습니다. 매 항목 사이에 IRQ를 풉니다.', '원문 호출은 completion 전용 locked 전체 깨움입니다. 잠금 보유와 RT 문맥 검사까지 같은 함수에서 확인하세요.')]),
('Completion 대기 핵심·잠금 해제와 표시 소비', 'kernel/sched/completion.c', 'do_wait_for_common',
 '공통 대기는 head 잠금이 잡힌 상태에서 done을 검사합니다. 표시가 없으면 스택 swait 항목으로 반복 대기하며 signal 검사, 등록, 대기 상태 설정, 잠금 해제, action, 잠금 재획득을 수행합니다. 반복 종료 뒤에는 내부 finish로 상태와 항목을 정리합니다. done이 있으면 일반 값은 하나 소비하고 UINT_MAX는 유지합니다. 성공 반환은 timeout이 0이더라도 최소 1로 조정됩니다.',
 '대기 중 raw 잠금을 보유하지 않는다는 점과 조건 검사·소비가 잠금 아래 수행된다는 점을 구별하세요. 동기화 완료 뒤 결과 사용은 호출자 작업입니다. 등록 정리와 완료 표시 소비도 별도의 단계를 표시합니다.',
 [('action을 실행하는 동안 head raw 잠금은 보유하나요?', '아닙니다. 풀고 실행한 뒤 다시 잡습니다.', '맞습니다. 전체 수면 동안 보유합니다.', '원문은 unlock_irq, action, lock_irq 순서입니다. 잠금은 표시와 연결을 보호하지만 수면 전체를 감싸지는 않습니다.'),
  ('보통 done 2에서 한 waiter가 성공하면 값은 무엇인가요?', '1입니다.', '반드시 0으로 초기화합니다.', '일반 완료 표시는 성공한 wait마다 하나 감소합니다. reinit의 전체 0 설정과 token 소비를 구별하세요.')]),
('Completion 공통 진입·IRQ 활성과 빈 annotation', 'kernel/sched/completion.c', '__wait_for_common',
 '공통 진입은 might_sleep, complete_acquire, raw_spin_lock_irq, 공통 대기, raw_spin_unlock_irq, complete_release 순서입니다. 이 IRQ 잠금은 이전 상태를 저장하는 irqsave 쌍이 아닙니다. 공식 문서는 IRQ가 활성인 잠들 수 있는 process 문맥에서 대기하라고 명시합니다. 이 버전 헤더의 complete_acquire와 complete_release 본체는 비어 있으므로 함수 이름만으로 별도 CPU acquire·release 명령이 실행된다고 해석하면 안 됩니다.',
 '대기는 IRQ 문맥, IRQ 비활성, 선점 비활성 등 잠들 수 없는 문맥에서 호출하지 마세요. annotation 이름, 실제 raw 잠금과 task 스케줄링의 역할을 나눕니다. 완료 전부터 mutex를 오래 보유하는 사용도 상대 작업의 잠금 순서와 함께 검토합니다.',
 [('공통 대기의 IRQ 잠금은 이전 IRQ 상태를 저장하나요?', '아닙니다. lock_irq와 unlock_irq 쌍입니다.', '맞습니다. 모든 raw 잠금은 irqsave입니다.', '원문 진입·종료 쌍을 확인하세요. IRQ가 꺼진 문맥에서 부적절한 활성화를 만들 수 있어 공식 사용 조건이 필요합니다.'),
  ('이 헤더의 complete_acquire에 독립 CPU 명령 본체가 있나요?', '아닙니다. 빈 inline 함수입니다.', '맞습니다. 이름만으로 모든 메모리 순서를 보장합니다.', '고정 버전의 실제 정의를 읽어야 합니다. annotation 이름과 실제 잠금·깨움의 메모리 순서 구현을 혼동하지 마세요.')]),
('Completion timeout·0 만료와 경계 성공 1', 'kernel/sched/completion.c', 'wait_for_completion_timeout',
 'uninterruptible timeout은 jiffies 단위 시간을 받고 완료하지 못한 만료에 0, 완료 성공에 최소 1인 잔여 시간을 반환합니다. 대기 action이 0을 돌려도 잠금을 다시 잡았을 때 done이 생겼으면 소비하고 1을 반환합니다. 이미 done이 있으면 timeout 0에서도 성공 1을 반환할 수 있습니다. 반면 done이 없고 timeout 0이면 공통 내부의 action 호출 경로에 들어갈 수 있어 atomic 문맥용 비차단 API와 같지 않습니다.',
 'unsigned long 반환 자료형과 0·양수 계약을 지키세요. 시간 단위를 변환하고 경계 성공을 별도로 이해합니다. 잠들 수 없는 문맥에서는 timeout 0을 대신 쓰지 말고 try_wait_for_completion의 계약을 확인합니다.',
 [('남은 시간 0이어도 done을 관측해 성공하면 무엇을 반환하나요?', '1입니다.', '무조건 실패 0입니다.', '공통 함수는 표시를 소비한 뒤 timeout ?: 1을 반환합니다. 만료 경계의 성공을 0 만료와 구별합니다.'),
  ('timeout 0이 try_wait와 같은 atomic 문맥용 API인가요?', '아닙니다. 공통 대기와 IRQ 활성 계약이 있습니다.', '맞습니다. 두 함수는 같은 본체입니다.', '공통 대기 진입에는 might_sleep와 lock_irq가 있습니다. 숫자 0만으로 API의 문맥 조건이 사라지지 않습니다.')]),
('Completion I/O 대기·action과 통계 문맥', 'kernel/sched/completion.c', 'wait_for_common_io',
 '일반 공통 wrapper는 schedule_timeout을 action으로 선택하고 I/O wrapper는 io_schedule_timeout을 선택합니다. done 검사와 소비, 대기열과 signal·timeout의 기본 구조는 공통입니다. I/O 변형은 기다리는 시간이 I/O 대기로 집계되는 문맥을 표현하며 디스크 요청을 직접 생성하거나 완료시키는 함수는 아닙니다. 시간 제한 없는 I/O wait는 void, 시간 제한 변형은 unsigned long을 반환합니다.',
 '완료 사건이 I/O 대기로 집계되어야 하는 사용 문맥인지 확인합니다. timeout 반환값은 일반 uninterruptible 시간 제한과 같은 방식으로 처리하세요. action 선택과 실제 작업 요청을 별도로 추적합니다.',
 [('I/O 공통 wrapper가 선택하는 action은 무엇인가요?', 'io_schedule_timeout입니다.', '항상 read syscall입니다.', '공통 함수의 action 인자를 확인하세요. 실제 I/O 요청 수행과 기다리는 task의 통계·스케줄링 문맥은 다른 동작입니다.'),
  ('I/O timeout도 완료 성공에 최소 1을 반환하나요?', '그렇습니다. 공통 소비·반환 계약입니다.', '아닙니다. 모든 I/O 성공은 음수입니다.', '두 wrapper는 같은 __wait_for_common을 사용합니다. action이 달라도 done 소비와 성공 반환의 기본 계약은 유지됩니다.')]),
('Completion interruptible·성공 0과 -ERESTARTSYS', 'kernel/sched/completion.c', 'wait_for_completion_interruptible',
 'interruptible의 공통 대기 state는 TASK_INTERRUPTIBLE입니다. 시간 제한 없는 wrapper는 공통 결과가 -ERESTARTSYS이면 오류를 전달하고 그 외 완료 성공을 0으로 바꿉니다. timeout 변형은 long으로 양수 완료, 0 만료, 음수 signal 오류를 그대로 전달합니다. 이미 done이 있는 경로는 공통 함수가 대기 반복에 들어가지 않으므로 pending signal이 있어도 표시를 소비하여 성공할 수 있습니다.',
 'timeout 없는 성공 0과 timeout의 성공 양수를 구별하세요. if(ret)만으로 성공을 검사하지 않습니다. 완료 표시와 signal을 언제 검사하는지 분기 순서로 확인합니다.',
 [('시간 제한 없는 interruptible의 성공 반환은 무엇인가요?', '0입니다.', '항상 남은 jiffies입니다.', 'wrapper는 공통 함수의 양수 성공을 0으로 정규화합니다. 시간 제한 변형의 long 반환과 구별해야 합니다.'),
  ('이미 done이 있는데 pending signal도 있으면 항상 실패하나요?', '아닙니다. 표시를 소비하고 성공할 수 있습니다.', '맞습니다. signal은 모든 경로보다 우선합니다.', '공통 함수는 done이 없을 때만 대기 반복의 signal 검사를 수행합니다. 준비된 완료 표시의 경로를 직접 확인하세요.')]),
('Completion killable·signal 분류와 정확한 자료형', 'kernel/sched/completion.c', 'wait_for_completion_killable',
 'killable은 TASK_KILLABLE을 선택하고 kill signal로 중단될 때 -ERESTARTSYS를 전달합니다. 일반 signal의 interruptible 대기와 같은 범위라고 가정하면 안 됩니다. 시간 제한 없는 함수의 실제 헤더·정의 반환 자료형은 int이며 timeout 변형은 long입니다. 문서 예시에 보이는 자료형보다 고정 버전의 선언과 정의를 함께 확인해야 C 호출 타입을 정확히 읽을 수 있습니다.',
 '일반 signal과 killable 상태에서 허용되는 signal을 구별합니다. 반환값을 정확한 자료형에 저장하고 양수·0·음수 계약을 함수별로 확인하세요. wait_for_completion_state는 지정 state를 같은 공통 구조에 전달합니다.',
 [('시간 제한 없는 killable의 실제 반환 자료형은 무엇인가요?', '이 버전에서는 int입니다.', '반드시 문서 예시와 같은 long입니다.', 'include/linux/completion.h와 실제 C 정의는 int입니다. 선언과 구현을 맞춰 확인하는 습관이 자료형 오해를 줄입니다.'),
  ('killable과 interruptible이 모든 signal을 같은 방식으로 허용하나요?', '아닙니다. 선택 state의 signal 계약이 다릅니다.', '맞습니다. 이름만 다르고 state는 같습니다.', '원문은 TASK_KILLABLE과 TASK_INTERRUPTIBLE을 구별합니다. 같은 오류 번호라도 중단을 허용하는 사건 범위가 다릅니다.')]),
('Completion try wait·빠른 조회와 잠금 아래 재검사', 'kernel/sched/completion.c', 'try_wait_for_completion',
 'try_wait는 READ_ONCE(done)이 0이면 바로 false를 반환합니다. 0이 아니면 irqsave raw 잠금을 잡고 done을 다시 검사합니다. 그 사이 다른 waiter가 소비해 0이 되었으면 false이며, 일반 표시가 남으면 하나 소비하고 true, UINT_MAX이면 줄이지 않고 true입니다. 대기열에 등록하거나 schedule하는 경로는 없습니다. 빠른 조회는 소비 성공의 확정이 아니며 잠금 아래 재검사가 필요합니다.',
 '잠들 수 없는 문맥에서 완료 표시를 소비할 수 있는지 확인할 때 사용 계약을 지키세요. false는 관측 시점에 소비하지 못했다는 결과입니다. true도 mutex 소유권이나 객체를 즉시 해제할 권리를 주는 것은 아닙니다.',
 [('첫 조회가 양수여도 잠금 아래 0이면 결과는 무엇인가요?', 'false입니다.', '항상 최초 조회를 따라 true입니다.', '함수는 잠금 아래 재검사합니다. 다른 소비자의 교차 실행으로 최초 조회와 최종 값이 달라질 수 있습니다.'),
  ('try wait가 스택 waiter를 대기열에 등록하나요?', '아닙니다. 비차단 소비 검사입니다.', '맞습니다. 잠들지 않아도 등록은 남습니다.', '본문은 조회, raw 잠금, 표시 소비만 수행합니다. wait_for_completion의 등록과 action 경로와 구별하세요.')]),
('Completion done 조회·waiter 수가 아닌 snapshot', 'kernel/sched/completion.c', 'completion_done',
 'completion_done은 첫 READ_ONCE(done)이 0이면 false를 반환합니다. 양수이면 raw 잠금을 한 번 잡았다 풀고 true를 반환하며, 잠금 아래 done을 다시 검사하거나 소비하지 않습니다. 따라서 대기열이 비었어도 표시가 0이면 false이고, 표시가 있으면 대기 항목이 남아 있어도 true일 수 있습니다. 최초 관측과 잠금 사이 다른 소비자가 0으로 만들면 반환 true와 현재 done 0이 함께 가능하므로 task 수나 최신 값의 소유권 조회로 해석하지 않습니다.',
 '현재·과거 완료 표시의 관측과 실제 waiter 종료를 구별하세요. complete_all 뒤에는 계속 true이므로 모든 waiter가 작업을 끝냈는지 판정할 수 없습니다. 다른 사용자 종료와 객체 수명은 별도 프로토콜로 보장합니다.',
 [('completion_done이 true이면 대기열이 반드시 비었나요?', '아닙니다. done 관측과 항목 수는 다릅니다.', '맞습니다. 리스트 길이를 직접 검사합니다.', '본문은 task_list를 읽지 않습니다. 특히 complete_all 뒤에 true라는 사실은 모든 사용자가 종료되었다는 보장이 아닙니다.'),
  ('잠금 아래 done을 다시 확인하고 하나 소비하나요?', '아닙니다. 재검사나 소비가 없습니다.', '맞습니다. try wait와 완전히 같은 본체입니다.', '두 함수를 비교하면 try wait에는 재검사·감소가 있고 completion_done에는 없습니다. 교차 실행 때 반환 의미가 달라집니다.')]),
('Completion 재사용·complete_all 이후의 종료 규약', 'include/linux/completion.h', 'reinit_completion',
 'complete_all의 영구 완료를 다음 사건 주기에 쓰려면 reinit으로 done을 0으로 바꿔야 합니다. 하지만 현재 waiter를 깨운 순간이 그 task의 후속 완료와 같지는 않습니다. 원문은 모든 waiter가 깨어나 사용을 마친 뒤 재초기화할 것을 요구합니다. 숫자 sentinel이 반복 complete_all에도 포화 상태로 남는다는 사실만으로 반복 통지가 올바른 사건 설계라고 증명할 수는 없습니다.',
 '이전 작업의 종료, 다음 작업의 초기화와 새 complete 호출을 외부 규약으로 분리하세요. completion_done을 이전 사용자 수 조회로 사용하지 않습니다. timeout·signal 조기 반환 뒤에도 남은 producer의 객체 참조를 정리합니다.',
 [('complete_all 호출 직후 아무 확인 없이 reinit해도 항상 안전한가요?', '아닙니다. 이전 사용자 종료를 보장해야 합니다.', '맞습니다. 깨움 호출이 모든 후속 작업을 끝냅니다.', '공식 문서는 모든 waiter가 깨어나 종료한 뒤 재초기화하도록 요구합니다. task 깨움과 객체 사용 종료는 다른 시점입니다.'),
  ('sentinel이 반복 통지에도 유지되면 사건 프로토콜도 자동으로 올바른가요?', '아닙니다. 수명과 사건 주기 계약이 별도로 필요합니다.', '맞습니다. 숫자가 wrap하지 않으면 모든 경쟁이 해결됩니다.', '포화 숫자 알고리즘은 overflow를 막습니다. 재사용·작업 취소·객체 수명 규약 전체를 대신하지는 않습니다.')])
]

def register(topic, q, detail):
    for title, path, symbol, principle, use, qa in ROWS:
        topic(title, '동기화', path, symbol,
              '실제 completion의 완료 표시·대기열·잠금과 반환값을 읽고 비동기 작업 완료 및 객체 수명의 사용 조건을 배웁니다.',
              principle, use,
              'done 값, 리스트 등록, IRQ·잠금 상태와 반환값을 나누고 작업 완료·깨움·사용 종료를 별도로 추적하세요.',
              *(q(*x) for x in qa), details=[
                  detail('원문 확인', 'Linux v6.12 completion.h와 kernel/sched/completion.c, Documentation/scheduler/completion.rst를 전체 읽고 선언·정의·사용 조건을 대조했습니다.'),
                  detail('실행 검증의 범위', '원문 함수를 직렬 task·raw 잠금·IRQ·action·signal·조회 교차 실행 모델에서 검사한 80,001건이 최적화 및 ASan·UBSan에서 각각 통과했습니다. 실제 RT 문맥·객체 해제 경쟁·SMP·물리적 시간 증명은 아닙니다.')])
